// Ice armor builds three visible cracks from real direct hits, then bursts after a tell.
const iceBearSheet=new Image();iceBearSheet.assetSrc='assets/ice-bear-v1.png';
function beginIceBear(e,mode='swipe'){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'iceBearArmor',bespoke:true,mode,angle,origin:{x:e.x,y:e.y},windup:mode==='fracture'?1:.85,fired:false};}
const iceBearHitBase=hit;hit=(e,d)=>{if(e.species!=='r5e4')return iceBearHitBase(e,d);let before=e.hp,direct=!e.dotTick&&Number.isFinite(d)&&d>0,armored=!(e.iceBearBroken>0),result=iceBearHitBase(e,d*(direct&&armored?.65:1));if(direct&&e.hp>0&&e.hp<before&&!(e.iceBearBroken>0)&&e.attack?.mode!=='fracture'){e.iceBearCracks=Math.min(3,(e.iceBearCracks||0)+1);if(e.iceBearCracks===3)beginIceBear(e,'fracture');}return result;};
function iceBearContains(a,point){let d=dist(a.origin,point);if(a.mode==='fracture')return d<=220+1e-8;let angle=Math.atan2(point.y-a.origin.y,point.x-a.origin.x)-a.angle;angle=Math.atan2(Math.sin(angle),Math.cos(angle));return d<=135+1e-8&&Math.abs(angle)<=Math.PI/3+1e-8;}
const iceBearAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e4')return iceBearAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);e.iceBearBroken=Math.max(0,(e.iceBearBroken||0)-dt);
 if(e.iceBearBroken>0){e.attack=null;e.state='idle';e.t=1.2;return;}
 let a=e.attack;if(a?.pattern!=='iceBearArmor'){
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=135&&clear){beginIceBear(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,62*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,26)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.origin)>24){if(a.mode==='fracture'){e.iceBearBroken=5;e.iceBearCracks=0;}e.attack=null;e.state='idle';e.t=1.5;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=a.windup){a.fired=true;e.struck=true;if(iceBearContains(a,p)&&lineClear(a.origin,p))hurt(a.mode==='fracture'?74:58);burst(e.x,e.y,a.mode==='fracture'?220:80,'#a9dcf2');playSound('impact',e.x,e.y);if(a.mode==='fracture'){e.iceBearBroken=Math.max(0,5-(e.elapsed-a.windup));e.iceBearCracks=0;e.attack=null;e.state='idle';e.t=1.2;return;}}
 if(e.elapsed>=1.65){e.attack=null;e.state='idle';e.t=1.8;}
};
const iceBearDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r5e4'||!iceBearSheet.complete||!iceBearSheet.naturalWidth||!iceBearSheet.naturalHeight)return iceBearDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0||e.iceBearBroken>0)f={row:2,col:3};else if(e.attack?.pattern==='iceBearArmor')f={row:2,col:e.attack.mode==='fracture'?2:e.attack.fired?1:0};let q=project(e.x,e.y),sw=iceBearSheet.naturalWidth/4,sh=iceBearSheet.naturalHeight/3,w=300,h=w*sh/sw,anchor=[.84,.8,.82][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,iceBearSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(iceBearSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;
};
const iceBearSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e4'?195:iceBearSizeBase(e);
const iceBearGroundBase=drawGroundEffects;drawGroundEffects=()=>{iceBearGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e4'):enemies)){if(e.species!=='r5e4'||e.hp<=0||!visibleAt(e.x,e.y))continue;let a=e.attack;if(e.iceBearBroken>0){groundRing(e.x,e.y,65,'#eccf8e',2);continue;}if(a?.pattern==='iceBearArmor'&&!a.fired){if(a.mode==='fracture'){groundRing(e.x,e.y,220,'#82d3f1',3);groundRing(e.x,e.y,220*Math.max(0,1-e.elapsed),'#dbf6ff',1);}else{let q=project(e.x,e.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.strokeStyle='#deb77d';ctx.fillStyle='#d69c5422';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,135,a.angle-Math.PI/3,a.angle+Math.PI/3);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}}let q=project(e.x,e.y);ctx.save();for(let i=0;i<3;i++){ctx.fillStyle=i<(e.iceBearCracks||0)?'#cef8ff':'#355062';ctx.beginPath();ctx.arc(q.x+(i-1)*11,q.y-110,3,0,Math.PI*2);ctx.fill();}ctx.restore();}};
